import time, math, threading, uuid, hashlib, hmac, os
class RoomHub:
    def __init__(self, password_hash=None):
        self.password_hash=password_hash or '2aff246a5d0b83a73856f916c1b0dd9aea2d8e04d9c00032def83bea13533674'; self.upload_access=set(); self.upload_tries={}; self.device_attempts={}
        self.lock=threading.RLock(); self.players={}; self.messages={}; self.errors={}; self.seen={}
    def update(self, pid, packet=None):
        with self.lock:
            now=time.monotonic()
            for key,p in list(self.players.items()):
                if now-p['_seen']>20:self.players.pop(key,None);self.seen.pop(key,None);self.errors.pop(key,None);self.upload_access.discard(key)
            if pid in self.players:self.players[pid]['_seen']=now
            if isinstance(packet,dict) and isinstance(packet.get('seq'),int) and packet['seq']>self.seen.get(pid,-1):
                self.seen[pid]=packet['seq']
                events=packet.get('events',[])
                if isinstance(events,list):
                    for item in events[:40]:
                        if not isinstance(item,dict):continue
                        kind=item.get('event');data=item.get('data');p=self.players.get(pid)
                        if kind=='join' and isinstance(data,dict):
                            room=''.join(c for c in str(data.get('room','main'))[:32] if c.isascii() and (c.isalnum() or c in '_-')) or 'main'
                            if sum(v['room']==room for k,v in self.players.items() if k!=pid)>=24:
                                self.errors[pid]='Бөлме толы. Басқа код таңдаңыз.';continue
                            device=str(data.get('device',''))[:64];device=device if len(device)==32 and all(c in '0123456789abcdef' for c in device) else pid
                            claimed=data.get('failures',0);claimed=claimed if isinstance(claimed,int) and not isinstance(claimed,bool) else 0
                            self.device_attempts[device]=max(self.device_attempts.get(device,0),max(0,min(5,claimed)))
                            self.players[pid]={'_device':device,'id':pid,'name':str(data.get('name','Оқырман'))[:24],'room':room,'x':0.,'z':7.,'rotation':0.,'outside':True,'seat':None,'appearance':{},'_seen':now}
                        elif p and kind=='unlock_upload':
                            device=p.get('_device',pid);tries=self.device_attempts.get(device,0)
                            if tries>=5:
                                self.upload_access.discard(pid);self.errors[pid]='Пароль 5 рет қате енгізілді. Осы браузерде мәзір бұғатталған.'
                            elif isinstance(data,str) and len(data)<=256 and hmac.compare_digest(hashlib.sha256(data.encode()).hexdigest(),self.password_hash):
                                self.upload_access.add(pid)
                            else:
                                tries+=1;self.device_attempts[device]=tries
                                if tries>=5:self.upload_access.discard(pid)
                                self.errors[pid]='Осы браузерде мәзір бұғатталған.' if tries>=5 else 'Пароль қате. Қалған мүмкіндік: '+str(5-tries)
                        elif p and kind=='lock_upload':self.upload_access.discard(pid)
                        elif p and kind=='move' and isinstance(data,dict):
                            for axis in ['x','z','rotation']:
                                v=data.get(axis)
                                if isinstance(v,(int,float)) and math.isfinite(v):p[axis]=max(-12,min(12,float(v)))
                            if isinstance(data.get('outside'),bool):p['outside']=data['outside']
                        elif p and kind=='seat':
                            if data is None:p['seat']=None
                            elif isinstance(data,int) and not isinstance(data,bool) and 0<=data<16 and not p['outside']:
                                if any(v['id']!=pid and v['room']==p['room'] and v['seat']==data for v in self.players.values()):self.errors[pid]='Бұл орын бос емес. Басқа орын таңдаңыз.'
                                else:p['seat']=data
                        elif p and kind=='appearance' and isinstance(data,dict):
                            p['appearance']={k:str(data.get(k,''))[:16] for k in ['coat','skin','hair']}
                        elif p and kind=='chat' and isinstance(data,str) and data.strip():
                            if now-p.get('_chat',-10)<1:continue
                            p['_chat']=now;messages=self.messages.setdefault(p['room'],[]);messages.append({'id':uuid.uuid4().hex,'name':p['name'],'message':data.strip()[:240]});del messages[:-60]
            p=self.players.get(pid);room=p['room'] if p else None
            peers=[{k:v for k,v in v.items() if not k.startswith('_')} for v in self.players.values() if v['room']==room]
            failures=self.device_attempts.get(p.get('_device',pid),0) if p else 0
            return {'menuFailures':failures,'menuLocked':failures>=5,'uploadAllowed':pid in self.upload_access and failures<5,'selfId':pid,'players':peers,'messages':self.messages.get(room,[]),'error':self.errors.pop(pid,None),'seq':self.seen.get(pid,-1)}

import sqlite3,json,hashlib,textwrap,time
from pathlib import Path
class SharedCatalog:
    def __init__(self,path):
        self.path=str(path);Path(self.path).parent.mkdir(parents=True,exist_ok=True)
        with self.connect() as db:
            db.execute('PRAGMA journal_mode=WAL')
            db.execute('CREATE TABLE IF NOT EXISTS books (id TEXT PRIMARY KEY,title TEXT NOT NULL,payload TEXT NOT NULL,source BLOB,filename TEXT)')
            db.execute('CREATE TABLE IF NOT EXISTS catalog_meta (key TEXT PRIMARY KEY,value INTEGER NOT NULL)')
            db.execute("INSERT OR IGNORE INTO catalog_meta VALUES ('revision',0)")
    def connect(self):return sqlite3.connect(self.path,timeout=15)
    def snapshot(self,known=None):
        with self.connect() as db:
            revision=db.execute("SELECT value FROM catalog_meta WHERE key='revision'").fetchone()[0]
            if known==revision:return revision,None
            books=[json.loads(row[0]) for row in db.execute('SELECT payload FROM books ORDER BY rowid')]
        return revision,books
    def put(self,book,source=b'',filename=''):
        validate_book(book)
        with self.connect() as db:
            db.execute('INSERT OR REPLACE INTO books VALUES (?,?,?,?,?)',(book['id'],book['title'],json.dumps(book,ensure_ascii=False),source,filename))
            db.execute("UPDATE catalog_meta SET value=value+1 WHERE key='revision'")
    def delete(self,identifier):
        with self.connect() as db:
            cursor=db.execute('DELETE FROM books WHERE id=?',(identifier,))
            if cursor.rowcount:db.execute("UPDATE catalog_meta SET value=value+1 WHERE key='revision'")
    def restore(self,books):
        if not isinstance(books,list) or len(books)>200:raise ValueError('200 кітапқа дейін қалпына келтіруге болады.')
        for book in books:validate_book(book)
        with self.connect() as db:
            for b in books:db.execute('INSERT OR REPLACE INTO books VALUES (?,?,?,?,?)',(b['id'],b['title'],json.dumps(b,ensure_ascii=False),b'',''))
            db.execute("UPDATE catalog_meta SET value=value+1 WHERE key='revision'")
def validate_book(book):
    if not isinstance(book,dict) or not isinstance(book.get('id'),str) or not 1<=len(book['id'])<=100 or not isinstance(book.get('title'),str) or not 1<=len(book['title'])<=150:raise ValueError('Кітап атауы немесе коды дұрыс емес.')
    pages=book.get('pages')
    if not isinstance(pages,list) or not 1<=len(pages)<=10000:raise ValueError('Кітап беттері дұрыс емес.')
    for page in pages:
        if not isinstance(page,list) or len(page)!=2 or any(not isinstance(t,str) for t in page) or len(page[0])>250 or len(page[1])>5000:raise ValueError('Бет мәтіні дұрыс емес.')
def split_reading_pages(text,title):
    words=text.replace('\x00','').split();pages=[];line=''
    for word in words:
        for part in textwrap.wrap(word,430) or ['']:
            if line and len(line)+1+len(part)>430:pages.append([title,line]);line=''
            line+=(' ' if line else '')+part
    if line:pages.append([title,line])
    return pages
def make_book(filename,data,title=''):
    if not 0<len(data)<=15*1024*1024:raise ValueError('Файл 15 МБ-тан аспасын.')
    title=(title.strip() or Path(filename).stem)[:150];pages=[]
    if filename.lower().endswith('.txt'):pages=split_reading_pages(data.decode('utf-8-sig'),title)
    elif filename.lower().endswith('.pdf'):
        import io
        from pypdf import PdfReader
        reader=PdfReader(io.BytesIO(data))
        if reader.is_encrypted:raise ValueError('Парольмен жабылған PDF орнына ашық PDF жүктеңіз.')
        if len(reader.pages)>500:raise ValueError('PDF 500 беттен аспасын.')
        for n,page in enumerate(reader.pages,1):pages.extend(split_reading_pages(page.extract_text() or '',title+' · '+str(n)))
    else:raise ValueError('PDF немесе UTF-8 TXT таңдаңыз.')
    if not pages:raise ValueError('Мәтін табылмады. Скан PDF үшін OCR қажет.')
    book={'id':'shared-'+hashlib.sha256(data+title.encode()).hexdigest(),'title':title,'subtitle':'Ортақ кітапхана','pages':pages};validate_book(book);return book

