@st.cache_resource
def room_hub():
    password=os.environ.get('PARAQ_UPLOAD_PASSWORD','')
    try:password=str(st.secrets.get('upload_password',password))
    except Exception:pass
    return RoomHub(hashlib.sha256(password.encode()).hexdigest() if password else None)
@st.cache_resource
def component_folder():
    folder=Path(tempfile.gettempdir())/('paraq-'+hashlib.sha256(HTML.encode()).hexdigest()[:16])
    folder.mkdir(exist_ok=True)
    (folder/'index.html').write_text(HTML,encoding='utf-8')
    return str(folder)
component=declare_component('paraq_world',path=component_folder())
if 'paraq_peer' not in st.session_state:st.session_state.paraq_peer=uuid.uuid4().hex
@st.cache_resource
def shared_catalog():
    directory=Path(os.environ.get('PARAQ_DATA_DIR',str(Path(__file__).parent/'data')))
    return SharedCatalog(directory/'library.sqlite3')
def is_admin_password(value):
    password=os.environ.get('PARAQ_UPLOAD_PASSWORD','')
    try:password=str(st.secrets.get('upload_password',password))
    except Exception:pass
    expected=hashlib.sha256(password.encode()).hexdigest() if password else '2aff246a5d0b83a73856f916c1b0dd9aea2d8e04d9c00032def83bea13533674'
    return hmac.compare_digest(hashlib.sha256(value.encode()).hexdigest(),expected)
if str(st.query_params.get('admin',''))=='1':
    st.markdown('<style>html,body,[data-testid="stAppViewContainer"]{overflow:auto!important}.block-container{padding:2rem!important;max-width:950px!important}</style>',unsafe_allow_html=True)
    st.title('Кітапхана иесінің кабинеті')
    if not st.session_state.get('catalog_admin'):
        attempts=st.session_state.get('admin_attempts',0)
        if attempts>=5:st.error('5 қате әрекет. Осы сессияда әкімшіге кіру жабылды.');st.stop()
        with st.form('admin_login',clear_on_submit=True):
            entered=st.text_input('Әкімші паролі',type='password',max_chars=256)
            login=st.form_submit_button('Кіру')
        if login:
            if is_admin_password(entered):st.session_state.catalog_admin=True;st.rerun()
            else:st.session_state.admin_attempts=attempts+1;st.error('Пароль қате. Қалған мүмкіндік: '+str(4-attempts))
        st.stop()
    if st.button('Кабинеттен шығу'):
        st.session_state.catalog_admin=False;st.query_params.clear();st.rerun()
    catalog=shared_catalog()
    st.info('Мұнда қосылған кітаптар барлық оқырманға көрінеді. Оқырмандар кітап қоса алмайды.')
    with st.form('add_shared_book',clear_on_submit=True):
        title=st.text_input('Кітап атауы',max_chars=150)
        upload=st.file_uploader('PDF немесе UTF-8 TXT · 15 МБ дейін',type=['pdf','txt'])
        submit=st.form_submit_button('Барлығына қосу')
    if submit:
        if upload is None:st.warning('Алдымен файл таңдаңыз.')
        else:
            try:
                raw=upload.getvalue();book=make_book(upload.name,raw,title);catalog.put(book,raw,upload.name);st.success('Қосылды: '+book['title']+' · '+str(len(book['pages']))+' оқу беті')
            except Exception as error:st.error('Жүктеу орындалмады: '+str(error))
    revision,books=catalog.snapshot()
    st.subheader('Ортақ кітаптар: '+str(len(books)))
    for book in books:
        with st.expander(book['title']+' · '+str(len(book['pages']))+' бет'):
            st.caption('Кітап коды: '+book['id'])
            sure=st.checkbox('Осы кітапты барлық оқырманнан алып тастауды растаймын',key='confirm_'+book['id'])
            if st.button('Кітапты өшіру',key='delete_'+book['id'],disabled=not sure):catalog.delete(book['id']);st.rerun()
    st.download_button('Базаның мәтіндік сақтық көшірмесін жүктеу',json.dumps(books,ensure_ascii=False,indent=2).encode(),file_name='paraq-books-backup.json',mime='application/json')
    with st.form('restore_shared_catalog'):
        backup=st.file_uploader('Сақтық көшірмеден кітаптарды қосу (JSON)',type=['json'])
        restore=st.form_submit_button('Көшірмені қалпына келтіру')
    if restore and backup:
        try:
            if backup.size>50*1024*1024:raise ValueError('Көшірме 50 МБ-тан аспасын.')
            catalog.restore(json.loads(backup.getvalue()));st.success('Кітаптар қалпына келтірілді.');st.rerun()
        except Exception as error:st.error(str(error))
    st.caption('Базаны ұзақ сақтау үшін PARAQ_DATA_DIR тұрақты дискіге бағытталсын. Хостинг файлдары қайта құрылса жергілікті база жоғалуы мүмкін; сақтық көшірмені жүктеп алыңыз.')
    st.stop()

@st.fragment(run_every=0.8)
def world():
    pid=st.session_state.paraq_peer
    packet=st.session_state.get('paraq_last_packet')
    if isinstance(packet,dict):
        for event in packet.get('events',[]):
            if isinstance(event,dict) and event.get('event')=='catalog_loaded' and isinstance(event.get('data'),int):st.session_state.paraq_catalog_ack=event['data']
    state=room_hub().update(pid,packet)
    catalog_revision,catalog_books=shared_catalog().snapshot(st.session_state.get('paraq_catalog_ack'))
    value=component(state=state,catalog=catalog_books,catalogVersion=catalog_revision,initialRoom=str(st.query_params.get('room','main'))[:32],key='paraq_world',default=None)
    if isinstance(value,dict):
        old=st.session_state.get('paraq_last_packet')
        if not old or value.get('seq',-1)>old.get('seq',-1):
            st.session_state.paraq_last_packet=value
world()
